import Style from './auth.module.css';
import { useState, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import signup from '../../api/auth/signup';

import emailSend from '../../api/auth/emailSend';
import emailVerify from '../../api/auth/emailVerify';
import { profileImageUrl } from '../../utils/serverOrigin';

export default function Signup() {
    const navs = useNavigate();

    const [username, setUsername] = useState('');
    const [password, setPassword] = useState('');
    const [email, setEmail] = useState('');
    const [code, setCode] = useState('');
    const [profileFile, setProfileFile] = useState(null);
    const [previewUrl, setPreviewUrl] = useState(null);
    const fileInputRef = useRef(null);

    const onPickFile = (e) => {
        const file = e.target.files?.[0];
        setProfileFile(file || null);
        if (previewUrl) {
            URL.revokeObjectURL(previewUrl);
        }
        if (file) {
            setPreviewUrl(URL.createObjectURL(file));
        } else {
            setPreviewUrl(null);
        }
    };

    const clearPhoto = () => {
        setProfileFile(null);
        if (previewUrl) URL.revokeObjectURL(previewUrl);
        setPreviewUrl(null);
        if (fileInputRef.current) fileInputRef.current.value = '';
    };

    const check = async () => {
        const verify = await emailVerifyFunction({ email, code });
        if (verify?.success) {
            const { success, message } = await signup({
                username,
                password,
                email,
                profileFile,
            });
            alert(message);
            if (success) {
                navs('/auth/signin');
            }
        } else {
            alert(verify?.message);
        }
    };

    const emailSendFunction = async ({ email }) => {
        const data = await emailSend({ email });
        if (data.success) {
            alert(data.message);
        } else {
            alert(data.message);
        }
    };

    const emailVerifyFunction = async ({ email, code }) => {
        const data = await emailVerify({ email, code });
        alert(data?.message || '오류');
        return data;
    };

    const defaultAvatar = profileImageUrl('/uploads/profiles/default.svg');

    return (
        <div className={Style.signupPage}>
            <div className={Style.signupCard}>
                <header className={Style.signupHeader}>
                    <h1>회원가입</h1>
                    <p className={Style.signupLead}>프로필 사진과 계정 정보를 입력해 주세요.</p>
                </header>

                <div className={Style.profileBlock}>
                    <div className={Style.avatarRing}>
                        <img
                            src={previewUrl || defaultAvatar}
                            alt="프로필 미리보기"
                            className={Style.avatarImg}
                        />
                    </div>
                    <div className={Style.profileActions}>
                        <input
                            ref={fileInputRef}
                            type="file"
                            accept="image/jpeg,image/png,image/gif,image/webp"
                            className={Style.fileInput}
                            id="profile-upload"
                            onChange={onPickFile}
                        />
                        <label htmlFor="profile-upload" className={Style.fileLabel}>
                            사진 선택
                        </label>
                        {profileFile ? (
                            <button type="button" className={Style.clearPhoto} onClick={clearPhoto}>
                                사진 제거
                            </button>
                        ) : null}
                    </div>
                    <p className={Style.profileHint}>2MB 이하 · JPG, PNG, GIF, WebP</p>
                </div>

                <div className={Style.inputs}>
                    <div className={Style.inputbox}>
                        <label htmlFor="username">닉네임</label>
                        <input
                            type="text"
                            id="username"
                            value={username}
                            onChange={(e) => setUsername(e.target.value)}
                            placeholder="16자 이하, 숫자 제외"
                            autoComplete="username"
                        />
                    </div>
                    <div className={Style.inputbox}>
                        <label htmlFor="password">비밀번호</label>
                        <input
                            type="password"
                            id="password"
                            value={password}
                            onChange={(e) => setPassword(e.target.value)}
                            placeholder="영문·숫자·!@# 8~12자"
                            autoComplete="new-password"
                        />
                    </div>
                    <div className={Style.inputbox}>
                        <label htmlFor="email">이메일</label>
                        <input
                            type="email"
                            id="email"
                            value={email}
                            onChange={(e) => setEmail(e.target.value)}
                            placeholder="example@mail.com"
                            autoComplete="email"
                        />
                    </div>

                    <div className={Style.emailRow}>
                        <button
                            type="button"
                            className={Style.ghostBtn}
                            onClick={() => emailSendFunction({ email })}
                        >
                            인증 코드 받기
                        </button>
                    </div>

                    <div className={Style.inputbox}>
                        <label htmlFor="emailCheck">인증 코드</label>
                        <input
                            type="text"
                            id="emailCheck"
                            value={code}
                            onChange={(e) => setCode(e.target.value)}
                            placeholder="6자리 코드"
                            inputMode="numeric"
                        />
                    </div>

                    <div className={Style.button}>
                        <button type="button" className={Style.primaryBtn} onClick={check}>
                            가입 완료
                        </button>
                        <button type="button" className={Style.secondaryBtn} onClick={() => navs('/auth/signin')}>
                            로그인으로
                        </button>
                    </div>
                </div>
            </div>
        </div>
    );
}
